package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="membership_requests")
public class MembershipRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="applicant_name") private String applicantName; private String email; @Column(name="cv_url") private String cvUrl; @Column(length=5000) private String motivation; @Column(name="password_hash") private String passwordHash; @Column(name="requested_role") private String requestedRole; public String getRequestedRole(){return requestedRole;} public void setRequestedRole(String requestedRole){this.requestedRole=requestedRole;} @Enumerated(EnumType.STRING) private MembershipRequestStatus status = MembershipRequestStatus.PENDING; @Column(name="reviewed_by") private Long reviewedBy; @Column(name="reviewed_at") private LocalDateTime reviewedAt; private String decisionReason; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getApplicantName(){return applicantName;} public void setApplicantName(String applicantName){this.applicantName=applicantName;} public String getEmail(){return email;} public void setEmail(String email){this.email=email;} public String getCvUrl(){return cvUrl;} public void setCvUrl(String cvUrl){this.cvUrl=cvUrl;} public String getMotivation(){return motivation;} public void setMotivation(String motivation){this.motivation=motivation;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String passwordHash){this.passwordHash=passwordHash;} public MembershipRequestStatus getStatus(){return status;} public void setStatus(MembershipRequestStatus status){this.status=status;} public Long getReviewedBy(){return reviewedBy;} public void setReviewedBy(Long reviewedBy){this.reviewedBy=reviewedBy;} public LocalDateTime getReviewedAt(){return reviewedAt;} public void setReviewedAt(LocalDateTime reviewedAt){this.reviewedAt=reviewedAt;} public String getDecisionReason(){return decisionReason;} public void setDecisionReason(String decisionReason){this.decisionReason=decisionReason;} }
